import { memo } from "preact/compat";

export const Icon = memo(function Icon({ path }) {
    return (
        <svg class="gml-icon" viewBox="0 0 24 24" width="32" height="32" aria-hidden="true" focusable="false">
            <path d={path} fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" />
        </svg>
    );
});

export const GameLink = memo(function GameLink({ game }) {
    return (
        <li class="gml-item" data-tone={game.tone}>
            <a class="gml-link" href={game.href} aria-label={game.label} data-tone={game.tone}>
                <Icon path={game.iconPath} />
                <span class="gml-title">{game.title}</span>
            </a>
        </li>
    );
});
