import { useMemo } from "preact/hooks";
import { useParsedData, useWidgetEvents } from "../../shared/lib/lifecycle.js";
import { normalizeGames } from "./lib/normalize.js";
import { t } from "./lib/i18n.js";
import { GameLink } from "./components.js";

export const TAG = "np-games-links";

export function Widget({ dataJson }) {
    const data = useParsedData(dataJson);
    const model = useMemo(() => (data ? normalizeGames(data) : null), [data]);
    const ref = useWidgetEvents(TAG);
    if (!model)
        return null;
    return (
        <div class="gml-root" ref={ref}>
            <h2 class="gml-heading">{model.heading}</h2>
            <ul class="gml-list">
                {model.games.map((game) => (
                    <GameLink key={game.id} game={game} />
                ))}
            </ul>
            <a class="gml-more" href={model.moreUrl} aria-label={t("games.moreLabel", { count: model.games.length })}>
                <span>{t("games.more")}</span>
            </a>
        </div>
    );
}
