import { assertValid } from "../../../shared/lib/validate.js";
import { formatCompact, formatNumber } from "../../../shared/lib/format.js";
import { icons, iconNames } from "../generated/icons.js";
import { lookup } from "../generated/directory.js";
import { schemas } from "./schema.js";
import { t } from "./i18n.js";

const FALLBACK_ICON = iconNames[0];

export function resolveIcon(name) {
    return icons[name] ?? icons[FALLBACK_ICON];
}

function normalizeGame(game, index) {
    const directoryRow = lookup(index + 1);
    return {
        id: game.id,
        href: `/spiele/${game.slug}`,
        title: game.title,
        category: game.category.label,
        tone: game.tone,
        iconPath: resolveIcon(game.icon),
        ratingText: formatNumber(game.rating, 1),
        playersText: formatCompact(game.players),
        label: t("games.itemLabel", { title: game.title, category: game.category.label }),
        badge: directoryRow ? directoryRow[2] : null,
    };
}

export function normalizeGames(block) {
    assertValid(schemas, "GamesBlock", block);
    return {
        id: block.id,
        heading: block.heading || t("games.heading"),
        moreUrl: block.moreUrl,
        games: block.games.map(normalizeGame),
    };
}
