// A small structural validator for GraphQL-style payloads. Schemas are plain
// objects: { __typename, fields: { name: type } } where a type is a primitive
// name, "T?" for optional, "[T]" for lists, or a nested schema reference.
export function validate(schemas, typeName, value, path = typeName, errors = []) {
    const schema = schemas[typeName];
    if (!schema) {
        errors.push(`${path}: unknown schema ${typeName}`);
        return errors;
    }
    if (value === null || typeof value !== "object") {
        errors.push(`${path}: expected object`);
        return errors;
    }
    if (value.__typename !== schema.typename)
        errors.push(`${path}: expected __typename ${schema.typename}, got ${value.__typename}`);
    for (const [field, spec] of Object.entries(schema.fields))
        checkField(schemas, spec, value[field], `${path}.${field}`, errors);
    return errors;
}

function checkField(schemas, spec, value, path, errors) {
    const optional = spec.endsWith("?");
    const type = optional ? spec.slice(0, -1) : spec;
    if (value === undefined || value === null) {
        if (!optional)
            errors.push(`${path}: missing`);
        return;
    }
    if (type.startsWith("[")) {
        if (!Array.isArray(value)) {
            errors.push(`${path}: expected list`);
            return;
        }
        const inner = type.slice(1, -1);
        value.forEach((item, index) => checkField(schemas, inner, item, `${path}[${index}]`, errors));
        return;
    }
    switch (type) {
    case "string":
    case "number":
    case "boolean":
        if (typeof value !== type)
            errors.push(`${path}: expected ${type}`);
        break;
    case "any":
        break;
    case "timestamp":
        if (Number.isNaN(Date.parse(value)))
            errors.push(`${path}: invalid timestamp`);
        break;
    default:
        validate(schemas, type, value, path, errors);
    }
}

export function assertValid(schemas, typeName, value) {
    const errors = validate(schemas, typeName, value);
    if (errors.length)
        console.warn(`[widget] ${errors.length} validation problem(s)`, errors.slice(0, 5));
    return value;
}

export function unwrapConnection(connection) {
    return connection ? connection.edges.map((edge) => edge.node) : [];
}
